 {planningBusy&&!planning&&!audit&&<p role="status" className="hint">Há uma solicitação de composição aguardando confirmação. <Link href={releaseLink(id,params,{view:'planning',tab:'composition'})}>Verificar resultado da composição →</Link></p>}
 {branchDecisionBusy&&audit&&<p role="status" className="hint">Há uma decisão do plano em revisão ou aguardando confirmação. <Link href={releaseLink(id,params,{tab:'composition',view:undefined})}>Voltar à decisão do plano →</Link></p>}
 <ReleaseCancellation release={release} persona={persona} role={role} hidden={audit} available={data.capabilities?.cancellationAvailable===true} blocked={loading||Boolean(error)||planningBusy||branchDecisionBusy} onChanged={next=>{setData(next);setError('');setRevision(value=>value+1);}} onRefresh={()=>setRevision(value=>value+1)} onBusyChange={setCancelBusy} onConfirmationChange={setCancelConfirmation}/>
