  <section className="panel" id="release-stories"><h2>Histórias da release</h2>{data.composition&&<p><Link href={releaseLink(id,params,{'composition.revision':data.composition.id,'compositionMembers.page':undefined})} scroll={false}>Consultar rastreabilidade do código →</Link></p>}{data.stories.length?<div className="real-release-detail-stories">{data.stories.map(story=><Link key={story.id} href={`/stories/${story.id}?tab=releases`}><strong>{story.key} · {story.name}</strong><span className="badge">PENDING</span>{story.storyLifecycle&&<small>Revisão atual da História; não valida a composição congelada nem a candidata QA.</small>}<StoryLifecycleStatus reading={story.storyLifecycle} compact stale={Boolean(error)||loading}/><PlanningReferenceStatus reading={story.referenceReading} compact stale={Boolean(error)||loading}/><small>{story.pendingReasons.filter(reason=>reason!==story.referenceReading?.message).join(' ')}</small></Link>)}</div>:<div className="real-release-empty-note"><strong>{release.compositionStatus==='OPEN'?'Esta release OPEN está vazia e é válida.':'Nenhuma História nesta composição.'}</strong><p>{release.compositionStatus==='OPEN'?'Outra pessoa autorizada pode escolher Histórias depois. Nenhum pacote ou implantação foi criado.':'A composição não comprova pacote ou implantação.'}</p></div>}</section>
